#!/usr/bin/env bash
# suite-managed (deploy) — regenerated by conform, do not edit by hand.
# The ONE way to run docker compose on this node: always the same files, always
# the node's secrets. Bare `docker compose -f deploy/docker-compose.prod.yml up`
# misses both — compose interpolates from deploy/.env while the secrets live in
# the repo-root .env (any `${VAR:?}` stops it, Life#90), and the node's own
# deploy/docker-compose.db.yml / docker-compose.override.yml are left out as
# soon as a -f is given (Life#133, AcademicAssistant's first prod deploy).
#
# Usage: bash deploy/compose.sh [--prod] <docker compose args...>
#   bash deploy/compose.sh --prod up -d        # production (nginx bundle)
#   bash deploy/compose.sh logs -f backend     # dev (Vite + hot reload)
# Files: docker-compose.yml, or docker-compose.prod.yml with --prod; then
# docker-compose.db.yml and docker-compose.override.yml when present.
set -euo pipefail
DEPLOY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE="docker-compose.yml"
if [[ "${1:-}" == "--prod" ]]; then
  BASE="docker-compose.prod.yml"
  shift
fi
ARGS=()
# Checked at runtime so the generated script stays device-agnostic.
if [[ -f "$DEPLOY_DIR/../.env" ]]; then
  ARGS+=(--env-file "$DEPLOY_DIR/../.env")
fi
ARGS+=(-f "$DEPLOY_DIR/$BASE")
for extra in docker-compose.db.yml docker-compose.override.yml; do
  if [[ -f "$DEPLOY_DIR/$extra" ]]; then
    ARGS+=(-f "$DEPLOY_DIR/$extra")
  fi
done
exec docker compose "${ARGS[@]}" "$@"
